using System.Text;
using System.Threading.Tasks;
using Xunit;

namespace Vibranium.Tests;

// self-fix-y4, step 5 (the forms the round-1 reviews found). A variable declared in the count of a shift, in the `^e` of a
// user indexer, under `is not`, or in either operand of `&&` / `||` (as a condition, a guard or a VALUE) is in scope for
// what follows, as in C#; the conditional's natural type is taken with both arms' variables in scope; and an operand
// inside a collection-literal element is not typed once more per candidate type. In scope is not assigned (VIB001).
public sealed class Round12SelfOperandScopeTests
{
