    // Level i is a collection-literal element whose operand (of a cast, an assignment, a `new`, an index) holds level
    // i + 1, an overloaded call with a literal argument (see BuildCollectionShape). The expected text is the .NET output.
    [Theory]
    [InlineData("cB", 2, "1\n")]
    [InlineData("cB", 6, "1\n")]
    [InlineData("cC", 2, "1\n")]
    [InlineData("cC", 6, "1\n")]
    [InlineData("cD", 2, "1\n")]
    [InlineData("cD", 6, "1\n")]
    [InlineData("cF", 2, "1\n")]
    [InlineData("cF", 6, "1\n")]
    [InlineData("cG", 2, "1\n")]
    [InlineData("cG", 6, "1\n")]
    public Task CollectionElementOperand_AcceptsWithNativeParity(string kind, int depth, string expected) =>
        Round12RuleWitness.AcceptAsync(BuildCollectionShape(kind, depth), expected);

    // The conversion classifier types an element once per candidate type (root N112); an operand inside the element must
    // not be typed once more per candidate on top of that (flat on xy1-r3, 2^depth with step 4 alone).
    [Theory]
    [InlineData("cB", 60)]
    [InlineData("cB", 98)]
    [InlineData("cC", 60)]
    [InlineData("cC", 65)]
    [InlineData("cD", 60)]
    [InlineData("cD", 65)]
    [InlineData("cF", 60)]
    [InlineData("cF", 65)]
    [InlineData("cG", 49)]
    public Task CollectionElementOperand_MaxNesting_ChecksWithinTimeBound(string kind, int depth) =>
        Round12SelfNaturalBranchTypeTests.CheckWithinTimeBoundAsync(BuildCollectionShape(kind, depth), $"collection element {kind} at depth {depth}");

    internal static string BuildCollectionShape(string kind, int depth)
    {
        string e = "1";
        for (int i = 0; i < depth; i++)
        {
            e = kind switch
            {
                "cB" => $"H.F([(int){e}])",
                "cC" => $"H.F([(k = {e})])",
                "cD" => $"H.F([new W({e}).V])",
                "cF" => $"H.F([ar[{e}]])",
                _ => $"H.F([(int)H.F([{e}]) + T.G(out int y{i})])",
            };
        }
        var sb = new StringBuilder();
        if (kind == "cC") sb.Append("int k = 0;\n");
        if (kind == "cF") sb.Append("Span<int> ar = [0, 1, 2, 3];\n");
        sb.Append($"WriteLine({e});\n");
        sb.Append("static class H { public static int F(Span<int> s) => s.Length; public static int F(ReadOnlySpan<bool> s) => 2; }\n");
        if (kind == "cD") sb.Append("sealed class W { public int V; public W(int v) { V = v; } }\n");
        if (kind == "cG") sb.Append("static class T { public static int G(out int v) { v = 0; return 0; } }\n");
        return sb.ToString();
    }
}
